  private async *attemptLoopRecovery(
    detail: string | undefined,
    signal: AbortSignal,
    prompt_id: string,
    boundedTurns: number,
    displayContent?: PartListUnion,
  ): AsyncGenerator<ServerGeminiStreamEvent, Turn> {
    // Clear the active detection so the agent can self-correct. The cumulative
    // strike count is preserved so a second detection terminates the session.
    this.loopDetector.clearDetection();

    // If recovery would exhaust the remaining turns, don't attempt it.
    if (boundedTurns <= 1) {
      yield { type: GeminiEventType.MaxSessionTurns };
      return new Turn(this.getChat(), prompt_id);
    }

    const detailText = detail ? ` ${detail}` : '';
    const recoveryRequest: PartListUnion = [
      {
        text: `System: Potential loop detected.${detailText} Please re-evaluate your recent actions and take a different approach to make progress toward the user's goal. Avoid repeating the same steps.`,
      },
    ];

    return yield* this.sendMessageStream(
      recoveryRequest,
      signal,
      prompt_id,
      boundedTurns - 1,
      false,
      displayContent,
    );
  }

